-- Prediction Query
SELECT (CAST(f."Free Meal Count (Ages 5-17)" AS REAL) / f."Enrollment (Ages 5-17)") AS eligible_free_rate FROM frpm AS f JOIN schools AS s ON f.CDSCode = s.CDSCode WHERE s.SOCType = 'Continuation High Schools' AND NOT f."Enrollment (Ages 5-17)" IS NULL AND f."Enrollment (Ages 5-17)" <> 0 ORDER BY eligible_free_rate ASC, f.cdscode NULLS LAST, s.cdscode NULLS LAST LIMIT 3;

